#!/bin/bash

# Run tests using Docker (useful when Go is not installed locally)
docker run --rm -v "$PWD":/app -w /app golang:1.21 go test -v -buildvcs=false "$@"

package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestConditionalCommandExecution(t *testing.T) {
	// Setup: Create a temporary directory for testing
	tmpDir := t.TempDir()
	testConfigPath := filepath.Join(tmpDir, "test-config.yml")
	testProjectDir := filepath.Join(tmpDir, "test-project")

	// Create test project directory
	if err := os.MkdirAll(testProjectDir, 0755); err != nil {
		t.Fatalf("Failed to create test project directory: %v", err)
	}

	// Create test package files
	packageJSON := filepath.Join(testProjectDir, "package.json")
	packageLock := filepath.Join(testProjectDir, "package-lock.json")
	outputFile := filepath.Join(testProjectDir, "output.txt")

	if err := os.WriteFile(packageJSON, []byte(`{"name":"test","version":"1.0.0"}`), 0644); err != nil {
		t.Fatalf("Failed to create package.json: %v", err)
	}

	if err := os.WriteFile(packageLock, []byte(`{"lockfileVersion":2}`), 0644); err != nil {
		t.Fatalf("Failed to create package-lock.json: %v", err)
	}

	// Create test config
	configContent := `shortcommands:
  - name: TestProject
    commands:
      - name: install
        description: Test conditional command execution
        cwd: ` + testProjectDir + `
        do:
          - echo "step1" > output.txt
          - command: echo "step2-cached" >> output.txt
            skip-if-unchanged:
              - package.json
              - package-lock.json
          - echo "step3" >> output.txt
`

	if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
		t.Fatalf("Failed to create test config: %v", err)
	}

	// Set environment variable for config
	oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
	os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
	defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

	// Test 1: First run - should execute all commands
	t.Run("FirstRun_ExecutesAllCommands", func(t *testing.T) {
		// Clean output file
		os.Remove(outputFile)

		exitCode := run([]string{"TestProject", "install"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check output file content
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		lines := strings.Split(strings.TrimSpace(string(content)), "\n")
		if len(lines) != 3 {
			t.Errorf("Expected 3 lines in output, got %d: %v", len(lines), lines)
		}

		if !strings.Contains(string(content), "step2-cached") {
			t.Errorf("Expected step2-cached in output file, got: %s", content)
		}
	})

	// Test 2: Second run without changes - should skip cached command
	t.Run("SecondRun_SkipsCachedCommand", func(t *testing.T) {
		// Clean output file
		os.Remove(outputFile)

		// Wait a moment to ensure cache is written
		time.Sleep(100 * time.Millisecond)

		exitCode := run([]string{"TestProject", "install"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check output file - should only have step1 and step3
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		lines := strings.Split(strings.TrimSpace(string(content)), "\n")
		if len(lines) != 2 {
			t.Errorf("Expected 2 lines in output (step2 skipped), got %d: %v", len(lines), lines)
		}

		if strings.Contains(string(content), "step2-cached") {
			t.Errorf("Step2 should have been skipped, but found it in output: %s", content)
		}
	})

	// Test 3: Modify file - should execute cached command again
	t.Run("ModifiedFile_ExecutesCachedCommand", func(t *testing.T) {
		// Modify package.json
		if err := os.WriteFile(packageJSON, []byte(`{"name":"test","version":"2.0.0"}`), 0644); err != nil {
			t.Fatalf("Failed to modify package.json: %v", err)
		}

		// Clean output file
		os.Remove(outputFile)

		// Wait a moment
		time.Sleep(100 * time.Millisecond)

		exitCode := run([]string{"TestProject", "install"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check output file - should have all 3 steps again
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		lines := strings.Split(strings.TrimSpace(string(content)), "\n")
		if len(lines) != 3 {
			t.Errorf("Expected 3 lines in output, got %d: %v", len(lines), lines)
		}

		if !strings.Contains(string(content), "step2-cached") {
			t.Errorf("Expected step2-cached in output file, got: %s", content)
		}
	})

	// Test 3b: Modify only package-lock.json - should also execute cached command
	t.Run("ModifiedPackageLock_ExecutesCachedCommand", func(t *testing.T) {
		// Modify package-lock.json (not package.json)
		if err := os.WriteFile(packageLock, []byte(`{"lockfileVersion":3}`), 0644); err != nil {
			t.Fatalf("Failed to modify package-lock.json: %v", err)
		}

		// Clean output file
		os.Remove(outputFile)

		// Wait a moment
		time.Sleep(100 * time.Millisecond)

		exitCode := run([]string{"TestProject", "install"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check output file - should have all 3 steps again
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		lines := strings.Split(strings.TrimSpace(string(content)), "\n")
		if len(lines) != 3 {
			t.Errorf("Expected 3 lines in output, got %d: %v", len(lines), lines)
		}

		if !strings.Contains(string(content), "step2-cached") {
			t.Errorf("Expected step2-cached in output file after package-lock.json change, got: %s", content)
		}
	})

	// Test 4: Force flag - should execute even with no changes
	t.Run("ForceFlag_ExecutesCachedCommand", func(t *testing.T) {
		// Clean output file
		os.Remove(outputFile)

		// Wait a moment
		time.Sleep(100 * time.Millisecond)

		exitCode := run([]string{"TestProject", "install"}, true, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check output file - should have all 3 steps
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		lines := strings.Split(strings.TrimSpace(string(content)), "\n")
		if len(lines) != 3 {
			t.Errorf("Expected 3 lines in output with --force, got %d: %v", len(lines), lines)
		}
	})

	// Test 5: Clear cache flag
	t.Run("ClearCacheFlag_RemovesCacheFiles", func(t *testing.T) {
		exitCode := run([]string{}, false, true)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0 for clear cache, got %d", exitCode)
		}

		// After clearing cache, next run should execute the cached command
		os.Remove(outputFile)
		time.Sleep(100 * time.Millisecond)

		exitCode = run([]string{"TestProject", "install"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Command after cache clear failed with exit code %d", exitCode)
		}

		// Check that all steps executed (cache was cleared)
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		if !strings.Contains(string(content), "step2-cached") {
			t.Errorf("Expected step2 to execute after cache clear, got: %s", content)
		}
	})
}

func TestBackwardCompatibility(t *testing.T) {
	// Test that old-style string commands still work
	tmpDir := t.TempDir()
	testConfigPath := filepath.Join(tmpDir, "test-config.yml")
	outputFile := filepath.Join(tmpDir, "output.txt")

	// Create config with only string commands (old style)
	configContent := `shortcommands:
  - name: OldStyle
    commands:
      - name: test
        description: Test backward compatibility
        cwd: ` + tmpDir + `
        do:
          - echo "command1" > output.txt
          - echo "command2" >> output.txt
          - echo "command3" >> output.txt
`

	if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
		t.Fatalf("Failed to create test config: %v", err)
	}

	// Set environment variable for config
	oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
	os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
	defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

	// Run command
	exitCode := run([]string{"OldStyle", "test"}, false, false)

	if exitCode != 0 {
		t.Fatalf("Expected exit code 0, got %d", exitCode)
	}

	// Check that all commands executed
	content, err := os.ReadFile(outputFile)
	if err != nil {
		t.Fatalf("Failed to read output file: %v", err)
	}

	lines := strings.Split(strings.TrimSpace(string(content)), "\n")
	if len(lines) != 3 {
		t.Errorf("Expected 3 lines in output, got %d: %v", len(lines), lines)
	}

	expected := []string{"command1", "command2", "command3"}
	for i, line := range lines {
		if !strings.Contains(line, expected[i]) {
			t.Errorf("Line %d: expected %s, got %s", i+1, expected[i], line)
		}
	}
}

func TestShortCommandLevelCwd(t *testing.T) {
	// Test that commands inherit the shortcommand-level cwd
	tmpDir := t.TempDir()
	testConfigPath := filepath.Join(tmpDir, "test-config.yml")
	shortCommandDir := filepath.Join(tmpDir, "shortcommand-dir")
	commandDir := filepath.Join(tmpDir, "command-dir")

	// Create test directories
	if err := os.MkdirAll(shortCommandDir, 0755); err != nil {
		t.Fatalf("Failed to create shortcommand directory: %v", err)
	}
	if err := os.MkdirAll(commandDir, 0755); err != nil {
		t.Fatalf("Failed to create command directory: %v", err)
	}

	t.Run("InheritsShortCommandCwd", func(t *testing.T) {
		// Create config with shortcommand-level cwd
		configContent := `shortcommands:
  - name: TestCwd
    cwd: ` + shortCommandDir + `
    commands:
      - name: test
        description: Test shortcommand-level cwd
        do:
          - pwd > output.txt
`

		if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
			t.Fatalf("Failed to create test config: %v", err)
		}

		// Set environment variable for config
		oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
		os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
		defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

		// Run command
		exitCode := run([]string{"TestCwd", "test"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check that command ran in shortCommandDir
		outputFile := filepath.Join(shortCommandDir, "output.txt")
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		pwd := strings.TrimSpace(string(content))
		if pwd != shortCommandDir {
			t.Errorf("Expected command to run in %s, but ran in %s", shortCommandDir, pwd)
		}
	})

	t.Run("CommandCwdOverridesShortCommandCwd", func(t *testing.T) {
		// Create config with both shortcommand-level and command-level cwd
		configContent := `shortcommands:
  - name: TestCwd
    cwd: ` + shortCommandDir + `
    commands:
      - name: test
        description: Test command-level cwd override
        cwd: ` + commandDir + `
        do:
          - pwd > output.txt
`

		if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
			t.Fatalf("Failed to create test config: %v", err)
		}

		// Set environment variable for config
		oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
		os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
		defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

		// Run command
		exitCode := run([]string{"TestCwd", "test"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check that command ran in commandDir (command-level cwd takes precedence)
		outputFile := filepath.Join(commandDir, "output.txt")
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		pwd := strings.TrimSpace(string(content))
		if pwd != commandDir {
			t.Errorf("Expected command to run in %s (command-level cwd), but ran in %s", commandDir, pwd)
		}
	})

	t.Run("MultipleCommandsShareShortCommandCwd", func(t *testing.T) {
		// Create config with multiple commands sharing shortcommand-level cwd
		configContent := `shortcommands:
  - name: TestCwd
    cwd: ` + shortCommandDir + `
    commands:
      - name: test1
        description: Test command 1
        do:
          - echo "test1" > output1.txt
      - name: test2
        description: Test command 2
        do:
          - echo "test2" > output2.txt
`

		if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
			t.Fatalf("Failed to create test config: %v", err)
		}

		// Set environment variable for config
		oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
		os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
		defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

		// Run first command
		exitCode := run([]string{"TestCwd", "test1"}, false, false)
		if exitCode != 0 {
			t.Fatalf("Expected exit code 0 for test1, got %d", exitCode)
		}

		// Run second command
		exitCode = run([]string{"TestCwd", "test2"}, false, false)
		if exitCode != 0 {
			t.Fatalf("Expected exit code 0 for test2, got %d", exitCode)
		}

		// Check that both commands created files in shortCommandDir
		output1File := filepath.Join(shortCommandDir, "output1.txt")
		output2File := filepath.Join(shortCommandDir, "output2.txt")

		if _, err := os.Stat(output1File); os.IsNotExist(err) {
			t.Errorf("Expected output1.txt to exist in %s", shortCommandDir)
		}

		if _, err := os.Stat(output2File); os.IsNotExist(err) {
			t.Errorf("Expected output2.txt to exist in %s", shortCommandDir)
		}
	})

	t.Run("ShortCommandCwdWithTilde", func(t *testing.T) {
		// Create config with tilde in shortcommand-level cwd
		configContent := `shortcommands:
  - name: TestCwd
    cwd: "~"
    commands:
      - name: test
        description: Test tilde expansion in shortcommand-level cwd
        do:
          - pwd > test-shortcommand-cwd.txt
`

		if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
			t.Fatalf("Failed to create test config: %v", err)
		}

		// Set environment variable for config
		oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
		os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
		defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

		// Run command
		exitCode := run([]string{"TestCwd", "test"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check that command ran in home directory
		homeDir, _ := os.UserHomeDir()
		outputFile := filepath.Join(homeDir, "test-shortcommand-cwd.txt")
		defer os.Remove(outputFile) // Clean up

		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		pwd := strings.TrimSpace(string(content))
		if pwd != homeDir {
			t.Errorf("Expected command to run in home directory %s, but ran in %s", homeDir, pwd)
		}
	})

	t.Run("ShortCommandCwdWithEnvVar", func(t *testing.T) {
		// Set a test environment variable
		testEnvDir := filepath.Join(tmpDir, "env-dir")
		if err := os.MkdirAll(testEnvDir, 0755); err != nil {
			t.Fatalf("Failed to create env directory: %v", err)
		}
		os.Setenv("TEST_CWD_DIR", testEnvDir)
		defer os.Unsetenv("TEST_CWD_DIR")

		// Create config with environment variable in shortcommand-level cwd
		configContent := `shortcommands:
  - name: TestCwd
    cwd: "$TEST_CWD_DIR"
    commands:
      - name: test
        description: Test env var expansion in shortcommand-level cwd
        do:
          - pwd > output.txt
`

		if err := os.WriteFile(testConfigPath, []byte(configContent), 0644); err != nil {
			t.Fatalf("Failed to create test config: %v", err)
		}

		// Set environment variable for config
		oldConfig := os.Getenv("SHORTCOMMAND_CONFIG")
		os.Setenv("SHORTCOMMAND_CONFIG", testConfigPath)
		defer os.Setenv("SHORTCOMMAND_CONFIG", oldConfig)

		// Run command
		exitCode := run([]string{"TestCwd", "test"}, false, false)

		if exitCode != 0 {
			t.Fatalf("Expected exit code 0, got %d", exitCode)
		}

		// Check that command ran in env directory
		outputFile := filepath.Join(testEnvDir, "output.txt")
		content, err := os.ReadFile(outputFile)
		if err != nil {
			t.Fatalf("Failed to read output file: %v", err)
		}

		pwd := strings.TrimSpace(string(content))
		if pwd != testEnvDir {
			t.Errorf("Expected command to run in env directory %s, but ran in %s", testEnvDir, pwd)
		}
	})
}

package main

import (
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"gopkg.in/yaml.v2"
)

// version is set via ldflags during build
var version = "dev"

type Config struct {
	ShortCommands []ShortCommand `yaml:"shortcommands"`
}

type ShortCommand struct {
	Name     string    `yaml:"name"`
	CurrentWorkingDirectory string   `yaml:"cwd"`
	Commands []Command `yaml:"commands"`
}

type Command struct {
	Name                    string   `yaml:"name"`
	Description             string   `yaml:"description"`
	CurrentWorkingDirectory string   `yaml:"cwd"`
	Do                      []DoStep `yaml:"do"`
}

type DoStep struct {
	Command         string
	SkipIfUnchanged []string
}

// UnmarshalYAML allows DoStep to accept both string and object formats
func (d *DoStep) UnmarshalYAML(unmarshal func(interface{}) error) error {
	// Try to unmarshal as a string first
	var str string
	if err := unmarshal(&str); err == nil {
		d.Command = str
		return nil
	}

	// If that fails, unmarshal as an object
	var obj struct {
		Command         string   `yaml:"command"`
		SkipIfUnchanged []string `yaml:"skip-if-unchanged"`
	}
	if err := unmarshal(&obj); err != nil {
		return err
	}
	d.Command = obj.Command
	d.SkipIfUnchanged = obj.SkipIfUnchanged
	return nil
}

type CacheData struct {
	Files   map[string]string `json:"files"`
	LastRun time.Time         `json:"last_run"`
}

func fileExists(path string) bool {
	_, err := os.Stat(path)

	if err == nil {
		return true
	}

	if os.IsNotExist(err) {
		return false
	}

	return false
}

var ConsoleColors = map[string]string{
	"Reset":  "\033[0m",
	"Red":    "\033[31m",
	"Yellow": "\033[33m",
}

func getCacheDir() string {
	home, _ := os.UserHomeDir()

	switch runtime.GOOS {
	case "darwin":
		return filepath.Join(home, "Library", "Caches", "shortcommand")
	case "windows":
		if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
			return filepath.Join(appData, "shortcommand", "cache")
		}
		return filepath.Join(home, "AppData", "Local", "shortcommand", "cache")
	default: // linux and others
		if xdgCache := os.Getenv("XDG_CACHE_HOME"); xdgCache != "" {
			return filepath.Join(xdgCache, "shortcommand")
		}
		return filepath.Join(home, ".cache", "shortcommand")
	}
}

func getCacheFilePath(shortCommandName, commandName, cwd string) string {
	// Create a unique identifier based on shortcommand name, command name, and cwd
	identifier := fmt.Sprintf("%s-%s-%s", shortCommandName, commandName, cwd)
	// Replace problematic characters
	identifier = strings.ReplaceAll(identifier, "/", "-")
	identifier = strings.ReplaceAll(identifier, "\\", "-")
	identifier = strings.ReplaceAll(identifier, "~", "")
	identifier = strings.ReplaceAll(identifier, " ", "-")
	identifier = strings.ToLower(identifier)

	cacheDir := getCacheDir()
	return filepath.Join(cacheDir, identifier+".json")
}

func calculateFileHash(filePath string) (string, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return "", err
	}
	defer file.Close()

	hash := sha256.New()
	if _, err := io.Copy(hash, file); err != nil {
		return "", err
	}

	return fmt.Sprintf("%x", hash.Sum(nil)), nil
}

func readCache(cacheFilePath string) (*CacheData, error) {
	data, err := os.ReadFile(cacheFilePath)
	if err != nil {
		return nil, err
	}

	var cache CacheData
	if err := json.Unmarshal(data, &cache); err != nil {
		return nil, err
	}

	return &cache, nil
}

func writeCache(cacheFilePath string, cache *CacheData) error {
	// Ensure cache directory exists
	cacheDir := filepath.Dir(cacheFilePath)
	if err := os.MkdirAll(cacheDir, 0755); err != nil {
		return err
	}

	data, err := json.MarshalIndent(cache, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(cacheFilePath, data, 0644)
}

func shouldSkipCommand(step DoStep, cwd string, cacheFilePath string) bool {
	if len(step.SkipIfUnchanged) == 0 {
		return false
	}

	// Read existing cache
	cache, err := readCache(cacheFilePath)
	if err != nil {
		// No cache or error reading - need to run
		return false
	}

	// Check all watched files
	for _, relPath := range step.SkipIfUnchanged {
		absPath := filepath.Join(cwd, relPath)

		// Calculate current hash
		currentHash, err := calculateFileHash(absPath)
		if err != nil {
			// File doesn't exist or can't read - need to run
			return false
		}

		// Check if hash changed
		cachedHash, exists := cache.Files[absPath]
		if !exists || cachedHash != currentHash {
			// File is new or changed - need to run
			return false
		}
	}

	// All files unchanged
	return true
}

func updateCache(step DoStep, cwd string, cacheFilePath string) error {
	if len(step.SkipIfUnchanged) == 0 {
		return nil
	}

	cache := &CacheData{
		Files:   make(map[string]string),
		LastRun: time.Now(),
	}

	// Calculate hashes for all watched files
	for _, relPath := range step.SkipIfUnchanged {
		absPath := filepath.Join(cwd, relPath)
		hash, err := calculateFileHash(absPath)
		if err != nil {
			// If we can't hash the file, don't cache it
			continue
		}
		cache.Files[absPath] = hash
	}

	return writeCache(cacheFilePath, cache)
}

func executeCommand(commandToRun string, currentWorkingDirectory string) error {
	cmd := exec.Command("sh", "-c", commandToRun)
	if currentWorkingDirectory != "" {
		currentWorkingDirectoryResolved := os.ExpandEnv(currentWorkingDirectory)
		if strings.HasPrefix(currentWorkingDirectoryResolved, "~") {
			home, _ := os.UserHomeDir()
			currentWorkingDirectoryResolved = home + currentWorkingDirectoryResolved[1:]
		}
		if !fileExists(currentWorkingDirectoryResolved) {
			fmt.Printf("%sUnable to find given working directory: %s%s\n", ConsoleColors["Red"], currentWorkingDirectory, ConsoleColors["Reset"])
		}
		cmd.Dir = currentWorkingDirectoryResolved
	}

	stdout := io.Writer(os.Stdout)
	stderr := io.Writer(os.Stderr)

	cmd.Stderr = stderr
	cmd.Stdout = stdout

	cmd.Start()

	return cmd.Wait()
}

func run(args []string, forceFlag, clearCacheFlag bool) int {
	// Handle --clear-cache
	if clearCacheFlag {
		cacheDir := getCacheDir()
		if err := os.RemoveAll(cacheDir); err != nil {
			fmt.Printf("%sError clearing cache: %v%s\n", ConsoleColors["Red"], err, ConsoleColors["Reset"])
			return 1
		}
		fmt.Printf("Cache cleared: %s\n", cacheDir)
		return 0
	}

	shortcommandPath := os.Getenv("SHORTCOMMAND_CONFIG")

	if shortcommandPath == "" {
		fmt.Println("SHORTCOMMAND_CONFIG env not found or empty")
		return 1
	}

	yamlFile, err := os.ReadFile(shortcommandPath)

	if err != nil {
		fmt.Println("Unable to find file specified in SHORTCOMMAND_CONFIG: ", shortcommandPath)
		return 1
	}

	var parsedConfig Config

	err = yaml.Unmarshal(yamlFile, &parsedConfig)
	if err != nil {
		fmt.Println("Invalid config file given")
		return 1
	}

	if len(args) < 1 {
		fmt.Println("Available commands")
		for _, shortCommand := range parsedConfig.ShortCommands {
			fmt.Printf("%s\n", shortCommand.Name)
			for _, command := range shortCommand.Commands {
				fmt.Printf("%s%s%s%s\n", "  ", command.Name, "\t", command.Description)
			}
		}
		return 0
	}

	if len(args) < 2 {
		for _, shortCommand := range parsedConfig.ShortCommands {
			if shortCommand.Name == args[0] {
				fmt.Printf("Available sub commands for %s\n", args[0])
				for _, command := range shortCommand.Commands {
					fmt.Printf("%s%s%s\n", command.Name, "\t", command.Description)
				}
				break
			}
		}
		return 0
	}

       for _, shortCommand := range parsedConfig.ShortCommands {
	       if shortCommand.Name == args[0] {
		       for _, command := range shortCommand.Commands {
			       if command.Name == args[1] {
				       fmt.Println(shortCommand.Name, ">", command.Name, ":", command.Description)

				       // Determine working directory: command > shortcommand > process cwd
				       cwd := command.CurrentWorkingDirectory
				       if cwd == "" {
					       cwd = shortCommand.CurrentWorkingDirectory
				       }
				       if cwd == "" {
					       cwd, _ = os.Getwd()
				       } else {
					       cwd = os.ExpandEnv(cwd)
					       if strings.HasPrefix(cwd, "~") {
						       home, _ := os.UserHomeDir()
						       cwd = home + cwd[1:]
					       }
				       }

				       cacheFilePath := getCacheFilePath(shortCommand.Name, command.Name, cwd)

				       for i, step := range command.Do {
					       // Check if we should skip this command
					       if !forceFlag && shouldSkipCommand(step, cwd, cacheFilePath) {
						       fmt.Printf("%s⏭️  Skipping: %s (no changes detected)%s\n",
							       ConsoleColors["Yellow"], step.Command, ConsoleColors["Reset"])
						       continue
					       }

					       fmt.Println(">", step.Command)
					       err = executeCommand(step.Command, cwd)

					       if err != nil {
						       if i < len(command.Do)-1 {
							       fmt.Printf("%sNot continuing with the next command in do sequence as previous command errored out%s\n", ConsoleColors["Red"], ConsoleColors["Reset"])
							       return 1
						       }
					       } else {
						       // Update cache if command succeeded and has skip-if-unchanged
						       if err := updateCache(step, cwd, cacheFilePath); err != nil {
							       // Just log the error, don't fail the command
							       fmt.Printf("%sWarning: Failed to update cache: %v%s\n",
								       ConsoleColors["Yellow"], err, ConsoleColors["Reset"])
						       }
					       }
				       }
				       fmt.Println()
				       return 0
			       }
		       }
		       break
	       }
       }

	fmt.Println("No matching command found for given arguments")
	return 1
}

func main() {
	// Parse command-line flags
	versionFlag := flag.Bool("version", false, "Print version information")
	forceFlag := flag.Bool("force", false, "Force execution, ignoring cache")
	clearCacheFlag := flag.Bool("clear-cache", false, "Clear all cache files")
	flag.Parse()

	// Handle version flag
	if *versionFlag {
		fmt.Printf("shortcommand version %s\n", version)
		os.Exit(0)
	}

	os.Exit(run(flag.Args(), *forceFlag, *clearCacheFlag))
}
